package com.univmar.quotation.domain;
import com.univmar.customer.domain.Customer; import com.univmar.project.domain.Project; import com.univmar.rfq.domain.QuoteRequest; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="quotation") public class Quotation { @Id private UUID id; @Column(nullable=false,unique=true,length=40) private String number; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id") private Customer customer; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="project_id") private Project project; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="rfq_id") private QuoteRequest rfq; @Column(name="sales_agent",nullable=false,length=320) private String salesAgent; private LocalDate expiryDate; @Column(precision=14,scale=2) private BigDecimal transport=BigDecimal.ZERO; @Column(name="payment_terms",columnDefinition="text") private String paymentTerms; @Column(columnDefinition="text") private String notes; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private QuotationStatus status=QuotationStatus.DRAFT; @Column(nullable=false) private int revision=1; @Column(name="subtotal",nullable=false,precision=14,scale=2) private BigDecimal subtotal=BigDecimal.ZERO; @Column(name="tax_total",nullable=false,precision=14,scale=2) private BigDecimal taxTotal=BigDecimal.ZERO; @Column(name="grand_total",nullable=false,precision=14,scale=2) private BigDecimal grandTotal=BigDecimal.ZERO; @Column(name="created_at",nullable=false) private Instant createdAt; @OneToMany(mappedBy="quotation",cascade=CascadeType.ALL,orphanRemoval=true) private final List<QuotationItem> items=new ArrayList<>(); protected Quotation(){} public Quotation(String number,Customer c,Project p,QuoteRequest r,String agent,LocalDate expiry,BigDecimal transport,String terms,String notes,int revision){id=UUID.randomUUID();this.number=number;customer=c;project=p;rfq=r;salesAgent=agent;expiryDate=expiry;this.transport=transport;paymentTerms=terms;this.notes=notes;this.revision=revision;} public void add(QuotationItem i){items.add(i);recalculate();} public void update(LocalDate e,BigDecimal t,String p,String n){expiryDate=e;transport=t;paymentTerms=p;notes=n;recalculate();} public void status(QuotationStatus s){status=s;} public void recalculate(){subtotal=items.stream().map(QuotationItem::net).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);taxTotal=items.stream().map(QuotationItem::tax).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);grandTotal=subtotal.add(taxTotal).add(transport).setScale(2,RoundingMode.HALF_UP);}@PrePersist void p(){createdAt=Instant.now();} public UUID getId(){return id;} public String getNumber(){return number;} public Customer getCustomer(){return customer;} public Project getProject(){return project;} public QuoteRequest getRfq(){return rfq;} public String getSalesAgent(){return salesAgent;} public LocalDate getExpiryDate(){return expiryDate;} public BigDecimal getTransport(){return transport;} public String getPaymentTerms(){return paymentTerms;} public String getNotes(){return notes;} public QuotationStatus getStatus(){return status;} public int getRevision(){return revision;} public BigDecimal getSubtotal(){return subtotal;} public BigDecimal getTaxTotal(){return taxTotal;} public BigDecimal getGrandTotal(){return grandTotal;} public Instant getCreatedAt(){return createdAt;} public List<QuotationItem> getItems(){return items;} }
